-- Applied directly to Supabase project ovchyktojhrbydigwmzq on 2026-11-26.
-- Migration: twende_initial_core_schema. Historical SQL; do not re-run on existing database.
-- No client-side financial, ride-state, approval or role writes are enabled.
begin;
create table public.profiles (user_id uuid primary key references auth.users(id), full_name text not null check (length(trim(full_name)) between 1 and 150), created_at timestamptz not null default now());
alter table public.profiles enable row level security;
revoke all on public.profiles from public, anon, authenticated;
grant select on public.profiles to authenticated;
grant select, insert, update, delete on public.profiles to service_role;
create table public.user_roles (user_id uuid references auth.users(id), role text not null check (role in ('passenger','driver','admin')), primary key(user_id,role));
alter table public.user_roles enable row level security;
revoke all on public.user_roles from public, anon, authenticated;
grant select on public.user_roles to authenticated;
grant select, insert, update, delete on public.user_roles to service_role;
create table public.driver_applications (user_id uuid primary key references auth.users(id), status text not null default 'pending' check(status in ('pending','approved','rejected','suspended')), created_at timestamptz not null default now());
alter table public.driver_applications enable row level security;
revoke all on public.driver_applications from public, anon, authenticated;
grant select on public.driver_applications to authenticated;
grant select, insert, update, delete on public.driver_applications to service_role;
create table public.driver_documents (id uuid primary key default gen_random_uuid(), driver_id uuid not null references public.driver_applications(user_id), kind text not null check(kind in ('identity','license','driver_photo','vehicle_registration','ownership','insurance','vehicle_photos','transport_license','phone_verification','criminal_record')), storage_path text, status text not null default 'pending' check(status in ('pending','verified','rejected')), unique(driver_id,kind));
alter table public.driver_documents enable row level security;
revoke all on public.driver_documents from public, anon, authenticated;
grant select on public.driver_documents to authenticated;
grant select, insert, update, delete on public.driver_documents to service_role;
create table public.vehicles (id uuid primary key default gen_random_uuid(), driver_id uuid not null references public.driver_applications(user_id), kind text not null check(kind in ('car','motorcycle')), plate text not null unique);
alter table public.vehicles enable row level security;
revoke all on public.vehicles from public, anon, authenticated;
grant select on public.vehicles to authenticated;
grant select, insert, update, delete on public.vehicles to service_role;
create table public.rides (id uuid primary key default gen_random_uuid(), passenger_id uuid not null references auth.users(id), driver_id uuid references public.driver_applications(user_id), origin text not null, destination text not null, vehicle_kind text not null check(vehicle_kind in ('car','motorcycle')), agreed_fare_minor bigint check(agreed_fare_minor > 0), status text not null default 'requested' check(status in ('requested','assigned','arrived','in_progress','completed','cancelled')), created_at timestamptz not null default now());
alter table public.rides enable row level security;
revoke all on public.rides from public, anon, authenticated;
grant select on public.rides to authenticated;
grant select, insert, update, delete on public.rides to service_role;
create table public.ride_offers (id uuid primary key default gen_random_uuid(), ride_id uuid not null references public.rides(id), driver_id uuid not null references public.driver_applications(user_id), price_minor bigint not null check(price_minor>0), offered_by text not null check(offered_by in ('driver','passenger')), status text not null default 'pending' check(status in ('pending','accepted','rejected','expired')), created_at timestamptz not null default now());
alter table public.ride_offers enable row level security;
revoke all on public.ride_offers from public, anon, authenticated;
grant select on public.ride_offers to authenticated;
grant select, insert, update, delete on public.ride_offers to service_role;
create table public.wallets (driver_id uuid primary key references public.driver_applications(user_id), currency text not null default 'MZN' check(currency='MZN'));
alter table public.wallets enable row level security;
revoke all on public.wallets from public, anon, authenticated;
grant select on public.wallets to authenticated;
grant select, insert, update, delete on public.wallets to service_role;
create table public.wallet_entries (id uuid primary key default gen_random_uuid(), driver_id uuid not null references public.wallets(driver_id), ride_id uuid references public.rides(id), amount_minor bigint not null check(amount_minor<>0), kind text not null check(kind in ('topup','commission','adjustment','refund')), idempotency_key text not null unique, created_at timestamptz not null default now());
alter table public.wallet_entries enable row level security;
revoke all on public.wallet_entries from public, anon, authenticated;
grant select on public.wallet_entries to authenticated;
grant select, insert, update, delete on public.wallet_entries to service_role;
create table public.platform_settings (id boolean primary key default true check(id), commission_bps integer not null default 1000 check(commission_bps between 0 and 10000), free_cancel_minutes integer not null default 2 check(free_cancel_minutes>=0), no_show_minutes integer not null default 5 check(no_show_minutes>=0), cancellation_fee_minor bigint check(cancellation_fee_minor>=0), absence_fee_minor bigint check(absence_fee_minor>=0));
alter table public.platform_settings enable row level security;
revoke all on public.platform_settings from public, anon, authenticated;
grant select on public.platform_settings to authenticated;
grant select, insert, update, delete on public.platform_settings to service_role;
create table public.cancellation_events (id uuid primary key default gen_random_uuid(), ride_id uuid not null references public.rides(id), actor_id uuid not null references auth.users(id), reason text not null, safety_exception boolean not null default false, fee_minor bigint check(fee_minor>=0), created_at timestamptz not null default now());
alter table public.cancellation_events enable row level security;
revoke all on public.cancellation_events from public, anon, authenticated;
grant select on public.cancellation_events to authenticated;
grant select, insert, update, delete on public.cancellation_events to service_role;
create table public.appeals (id uuid primary key default gen_random_uuid(), cancellation_id uuid not null references public.cancellation_events(id), appellant_id uuid not null references auth.users(id), reason text not null, status text not null default 'pending' check(status in ('pending','accepted','rejected')));
alter table public.appeals enable row level security;
revoke all on public.appeals from public, anon, authenticated;
grant select on public.appeals to authenticated;
grant select, insert, update, delete on public.appeals to service_role;
create table public.audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_id uuid, created_at timestamptz not null default now());
alter table public.audit_events enable row level security;
revoke all on public.audit_events from public, anon, authenticated;
grant select on public.audit_events to authenticated;
grant select, insert, update, delete on public.audit_events to service_role;
create policy profiles_read on public.profiles for select to authenticated using (user_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
create policy user_roles_read on public.user_roles for select to authenticated using (user_id = (select auth.uid()));
create policy driver_applications_read on public.driver_applications for select to authenticated using (user_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
create policy driver_documents_read on public.driver_documents for select to authenticated using (driver_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
create policy vehicles_read on public.vehicles for select to authenticated using (driver_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
create policy rides_read on public.rides for select to authenticated using (passenger_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin') or driver_id = (select auth.uid()));
create policy ride_offers_read on public.ride_offers for select to authenticated using (driver_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin') or exists(select 1 from public.rides x where x.id = ride_id and x.passenger_id = (select auth.uid())));
create policy wallets_read on public.wallets for select to authenticated using (driver_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
create policy wallet_entries_read on public.wallet_entries for select to authenticated using (driver_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
create policy platform_settings_read on public.platform_settings for select to authenticated using (true);
create policy cancellation_events_read on public.cancellation_events for select to authenticated using (actor_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
create policy appeals_read on public.appeals for select to authenticated using (appellant_id = (select auth.uid()) or exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
create policy audit_events_read on public.audit_events for select to authenticated using (exists (select 1 from public.user_roles r where r.user_id = (select auth.uid()) and r.role = 'admin'));
grant insert (user_id,full_name), update (full_name) on public.profiles to authenticated;
create policy profiles_insert on public.profiles for insert to authenticated with check (user_id = (select auth.uid()));
create policy profiles_update on public.profiles for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
grant insert (user_id) on public.driver_applications to authenticated;
create policy driver_application_insert on public.driver_applications for insert to authenticated with check (user_id = (select auth.uid()) and status = 'pending');
create index rides_passenger_idx on public.rides(passenger_id);
create index rides_driver_idx on public.rides(driver_id);
create index ride_offers_ride_idx on public.ride_offers(ride_id);
create index ride_offers_driver_idx on public.ride_offers(driver_id);
create index wallet_entries_driver_idx on public.wallet_entries(driver_id);
create unique index wallet_one_commission_per_ride on public.wallet_entries(ride_id) where kind='commission' and ride_id is not null;
insert into public.platform_settings(id) values(true);
commit;
